onRecordAfterCreateSuccess((e)=>{try{const email=e.record.get('email');const message=new MailerMessage({from:{name:'HelloB2C'},to:[{address:email}],subject:'We have received your HelloB2C enquiry',html:'<h2>Thank you for sharing your brief.</h2><p>Your enquiry has been saved. The HelloB2C team will review your requirements and follow up using the email you provided.</p><p>This is an acknowledgement, not a project or appointment confirmation.</p>'});$app.newMailClient().send(message);}catch(err){$app.logger().error('Enquiry acknowledgement failed','error',String(err));}e.next();},'enquiries');
